def sha_bytes(data):
    return hashlib.sha256(data).hexdigest()

def decode(rel):
    return gzip.decompress(base64.b64decode(BLOBS[rel]))

def strip_comments(source):
    source = re.sub(r'/\*.*?\*/', '', source, flags=re.S)
    return re.sub(r'//.*', '', source)

def validate_type_aware_bindings(root):
    owners = [
        root/'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java',
        root/'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2WronskiAlignment.java',
        root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java',
    ]
    problems=[]; invocations=0
    call_re=re.compile(r'useAssetProgram\(\s*"motionv2/([^"]+)"(?:\s*,\s*(true|false))?\s*\)')
    resource_re=re.compile(r'\buniform\s+(?:(?:highp|mediump|lowp|readonly|writeonly|coherent|volatile|restrict)\s+)*(u?i?sampler2D|u?i?image2D)\s+([A-Za-z_]\w*)')
    regular_re=re.compile(r'\buniform\s+(?:(?:highp|mediump|lowp)\s+)?(?!u?i?(?:sampler2D|image2D)\b)(?:bool|int|uint|float|vec[234]|ivec[234]|uvec[234]|mat[234])\s+([A-Za-z_]\w*)\s*(?:\[[^;]*\])?\s*;')
    buffer_re=re.compile(r'layout\s*\([^)]*std430[^)]*\)\s*(?:readonly\s+|writeonly\s+|coherent\s+|volatile\s+|restrict\s+)*buffer\s+([A-Za-z_]\w*)\s*\{')
    for owner in owners:
        java=owner.read_text(); calls=list(call_re.finditer(java))
        for index,match in enumerate(calls):
            invocations += 1; name=match.group(1)
            shader=root/f'app/src/main/assets/shaders/motionv2/{name}.glsl'
            if not shader.is_file(): problems.append((owner.name,name,'missing shader')); continue
            segment=java[match.end():(calls[index+1].start() if index+1<len(calls) else len(java))]
            source=strip_comments(shader.read_text())
            resources={m.group(2):m.group(1) for m in resource_re.finditer(source)}
            regular={m.group(1) for m in regular_re.finditer(source)}
            buffers={m.group(1) for m in buffer_re.finditer(source)}
            sampler_calls=set(re.findall(r'(?<!Compute)setTexture\(\s*"([^"]+)"',segment))
            image_calls=set(re.findall(r'setTextureCompute\(\s*"([^"]+)"',segment))
            var_calls=set(re.findall(r'setVar(?:1|U)?\(\s*"([^"]+)"',segment))
            buffer_calls=set(re.findall(r'setBufferCompute\(\s*"([^"]+)"',segment))
            for var,typ in resources.items():
                if typ.endswith('sampler2D'):
                    if var not in sampler_calls: problems.append((owner.name,name,var,typ,'missing setTexture'))
                    if var in image_calls: problems.append((owner.name,name,var,typ,'illegal setTextureCompute'))
                else:
                    if var not in image_calls: problems.append((owner.name,name,var,typ,'missing setTextureCompute'))
                    if var in sampler_calls: problems.append((owner.name,name,var,typ,'illegal setTexture'))
            for var in regular:
                if var not in var_calls: problems.append((owner.name,name,var,'regular','missing setVar'))
            for var in buffers:
                if var not in buffer_calls: problems.append((owner.name,name,var,'buffer','missing setBufferCompute'))
            for var in sampler_calls:
                if var not in resources or not resources[var].endswith('sampler2D'):
                    problems.append((owner.name,name,var,'host setTexture','undeclared or non-sampler'))
            for var in image_calls:
                if var not in resources or not resources[var].endswith('image2D') or resources[var].endswith('sampler2D'):
                    problems.append((owner.name,name,var,'host setTextureCompute','undeclared or non-image'))
            for var in buffer_calls:
                if var not in buffers: problems.append((owner.name,name,var,'host setBufferCompute','undeclared buffer'))
            for var in var_calls:
                if var not in regular: problems.append((owner.name,name,var,'host setVar','undeclared or non-regular uniform'))
    if problems: raise RuntimeError('type-aware Motion binding failure: '+repr(problems))
    return invocations

def validate(root):
    for rel,expected in POST.items():
        p=root/rel
        if not p.is_file(): raise RuntimeError('missing post file '+rel)
        actual=sha_bytes(p.read_bytes())
        if actual!=expected: raise RuntimeError(f'post hash mismatch {rel}: {actual} != {expected}')
    recon=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java').read_text()
    cap=(root/'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java').read_text()
    post=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java').read_text()
    inputj=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java').read_text()
    rcd=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java').read_text()
    glb=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/GLBuffer.java').read_text()
    required=[
        (recon,'IRIS_26489_BJZHOU_PERSISTENT_BAYER_HOST'),
        (recon,'IRIS_26489_ADMISSION_EQUALS_ACCUMULATOR_CONTRIBUTION_INVARIANT'),
        (recon,'IRIS_26489_BJZHOU_BAYER_NORMALIZE_EXACTLY_ONCE'),
        (recon,'IRIS_26489_BENTO_SHORT_SENSOR_DOMAIN_BAYER_RECOVERY'),
        (cap,'IRIS_26489_SHORT_RAW_PRE_RESULT_STAGING_OWNER'),
        (cap,'IRIS_26489_SHORT_RAW_CALLBACK_BEFORE_RING_DRAIN'),
        (cap,'IRIS_26489_SHORT_STAGE_COPY_SKIPPED'),
        (post,'IRIS_26489_FUSED_BAYER_CANONICAL_POST_GRAPH'),
        (inputj,'IRIS_26489_FUSED_BAYER_FLOAT32_BRIDGE_OWNER'),
        (rcd,'IRIS_26489_POSTMERGE_RCD_DEMOSAIC_OWNER'),
        (rcd,'implementation=bandedDirectionalRcd'),
        (glb,'IRIS_26489_GPU_ONLY_SSBO_ALLOCATION'),
    ]
    for source,token in required:
        if token not in source: raise RuntimeError('missing architecture marker '+token)
    for retired in ('mfsr_low_support_reference','direct_rgb_accumulate','mfsr_finalize','short_highlight_recover','rcd_postmerge_demosaic'):
        if f'useAssetProgram("motionv2/{retired}"' in recon or f'useAssetProgram("motionv2/{retired}"' in rcd:
            raise RuntimeError('retired active graph survived: '+retired)
    if recon.count('useAssetProgram("motionv2/mfsr_bayer_normalize", true)') != 1:
        raise RuntimeError('Bayer normalization must have exactly one host invocation')
    if 'iris26489AdmittedFrames != iris26489ContributedFrames' not in recon or 'iris26489AdmittedFrames != iris26489ExpectedAdmittedFrames' not in recon:
        raise RuntimeError('admitted/contributed/expected invariant missing')
    if 'boolean directRgbCarrier = false;' not in post or 'new MotionV2RcdDemosaic()' not in post:
        raise RuntimeError('standard Bayer post graph is not fused-Bayer -> postmerge RCD owner')
    if 'directRgbFullRes' in inputj: raise RuntimeError('old direct-RGB bridge carrier survived')
    if 'new GLBuffer(int size' in glb: raise RuntimeError('unexpected malformed GLBuffer edit')
    if 'this(size,mFormat,GL_STATIC_DRAW,true);' not in glb or 'this(size,mFormat,mode,true);' not in glb:
        raise RuntimeError('legacy GLBuffer constructors no longer preserve CPU-mirror semantics')
    rcd_names=['rcd26489_populate','rcd26489_vh_direction','rcd26489_lpf','rcd26489_green','rcd26489_diag_residual','rcd26489_diag_direction','rcd26489_opposite','rcd26489_green_rb','rcd26489_write']
    for name in rcd_names:
        if rcd.count(f'useAssetProgram("motionv2/{name}", true)') != 1:
            raise RuntimeError('faithful RCD stage invocation mismatch '+name)
    if 'PPG' in (root/'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl').read_text():
        raise RuntimeError('PPG leaked into RCD populate stage')
    write=(root/'app/src/main/assets/shaders/motionv2/rcd26489_write.glsl').read_text()
    if 'boundary=gp.x<9' not in write or 'rgb=ppg(lp)' not in write:
        raise RuntimeError('PPG is not confined to the true image border')
    old=(root/'app/src/main/assets/shaders/motionv2/cfa_demosaic.glsl').read_text()
    if 'IRIS_26460_CROSS_PHASE_PLATEAU_CHROMA' not in old:
        raise RuntimeError('historical rejected shader marker unexpectedly changed')
    invocations=validate_type_aware_bindings(root)
    return invocations

def apply(root):
    root=Path(root)
    for rel,expected in PRE.items():
        p=root/rel
        if expected is None:
            if p.exists(): raise RuntimeError('new-file precondition violated: '+rel)
        else:
            if not p.is_file(): raise RuntimeError('missing pre file '+rel)
            actual=sha_bytes(p.read_bytes())
            if actual!=expected: raise RuntimeError(f'pre hash mismatch {rel}: {actual} != {expected}')
    for rel in BLOBS:
        p=root/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(decode(rel))
    n=validate(root)
    print(f'26489 transform PASS files={len(BLOBS)} typeAwareInvocations={n}')

def self_test():
    for rel,expected in POST.items():
        actual=sha_bytes(decode(rel))
        if actual!=expected: raise RuntimeError(f'embedded blob hash mismatch {rel}: {actual} != {expected}')
    if len(BLOBS)!=20: raise RuntimeError('expected 20-file 26489 transform')
    print('26489 transform self-test PASS embeddedFiles=20')

if __name__=='__main__':
    if len(sys.argv)==2 and sys.argv[1]=='--self-test': self_test()
    elif len(sys.argv)==2: apply(sys.argv[1])
    else: raise SystemExit('usage: transform_26489_bjzhou_host_bayer_rcd_v2.py <repo-root> | --self-test')
